/** What a contract file names, where it names it: for hover and go to definition in the editor. */
import { contractOccurrences } from '@flowpact/lint';
import { describe, expect, it } from 'vitest';

const CALLEE = [
  '# Generated by flowpact — do not edit by hand. Run `flowpact generate` to update.',
  'version: 1',
  'kind: workflow',
  'path: .github/workflows/callee.yml',
  'interface:',
  '  inputs:',
  '    name:',
  '      type: string',
  '  dispatchInputs:',
  '    mode: { type: string }',
  '  secrets:',
  '    token: { required: true }',
  '  outputs:',
  '    greeting:',
  '      value: ${{ jobs.greet.outputs.text }}',
  'consumers:',
  '  - from: .github/workflows/caller.yml',
  '    job: call',
  '    passes:',
  '      - name',
  '    reads: [greeting]',
  '',
].join('\n');

const CALLER = [
  'version: 1',
  'kind: workflow',
  'path: .github/workflows/caller.yml',
  'interface:',
  '  inputs: {}',
  'calls:',
  '  - job: call',
  '    uses: .github/workflows/callee.yml',
  '  - job: remote',
  '    uses: octo/ship/.github/workflows/deploy.yml@v1',
  '',
].join('\n');

/** Each occurrence's symbol, and the text its location covers. */
const named = (text: string) =>
  contractOccurrences('c.yaml', text).map((o) => {
    expect(o.loc.line).toBe(o.loc.endLine);
    return [o.symbol, text.split('\n')[o.loc.line - 1]!.slice(o.loc.column - 1, o.loc.endColumn - 1)];
  });

describe('contractOccurrences', () => {
  it('names the unit, its interface, and its consumers with what they pass and read', () => {
    const unit = '.github/workflows/callee.yml';
    expect(named(CALLEE)).toEqual([
      [unit, unit],
      [`${unit}#inputs.name`, 'name'],
      [`${unit}#inputs.mode`, 'mode'],
      [`${unit}#secrets.token`, 'token'],
      [`${unit}#outputs.greeting`, 'greeting'],
      ['.github/workflows/caller.yml', '.github/workflows/caller.yml'],
      ['.github/workflows/caller.yml#jobs.call', 'call'],
      [`${unit}#inputs.name`, 'name'],
      [`${unit}#outputs.greeting`, 'greeting'],
    ]);
  });

  it('names the jobs that call, and what they call, local or remote', () => {
    expect(named(CALLER)).toEqual([
      ['.github/workflows/caller.yml', '.github/workflows/caller.yml'],
      ['.github/workflows/caller.yml#jobs.call', 'call'],
      ['.github/workflows/callee.yml', '.github/workflows/callee.yml'],
      ['.github/workflows/caller.yml#jobs.remote', 'remote'],
      ['remote:octo/ship/.github/workflows/deploy.yml@v1', 'octo/ship/.github/workflows/deploy.yml@v1'],
    ]);
  });

  it('names nothing in a file that is not a contract', () => {
    expect(contractOccurrences('c.yaml', 'version: 1\ninterface:\n  inputs:\n    a: {}\n')).toEqual([]);
    expect(contractOccurrences('c.yaml', '<<<<<<< HEAD\n')).toEqual([]);
  });
});
